          readUint32() { return 0; },
          readInt32() { return 0; },
          readUint16() { return 0; },
          readUint8() { return 0; },
          readString() { return ""; },
          readCString() { return ""; },
          readUint8Array() { return new Uint8Array(0); },
          byteLength: bytes.length,
